// Create binary 'data' from JSON manifest (S3 node expects 'data' field)
// Preserve the canonical manifest key and repo-built order upsert payload.
const input = $input.first().json || {};
const manifest = input.manifest;
const orderId = input.orderId || input.orderUpsert?.orderId || input.orderUpsert?.order_id || null;
const manifestKey = input.r2Key || input.manifestKey || input.orderUpsert?.one_manifest_url || input.manifest?.artifacts?.manifestKey || null;

if (!manifest) {
  throw new Error('Missing manifest from Build 1‑manifest.json');
}

if (!manifestKey) {
  throw new Error('Missing manifest key from Build 1‑manifest.json');
}

const data = Buffer.from(JSON.stringify(manifest), 'utf8');

return [{
  json: {
    r2Key: manifestKey,
    manifestKey,
    orderId,
    manifest,
    orderUpsert: input.orderUpsert || null,
    _config: input._config,
  },
  binary: {
    data: {
      data,
      mimeType: 'application/json',
      fileName: '1-manifest.json',
    },
  },
}];

// Build fallback (no upload): keep the canonical manifest payload from the repo-owned build step.
const input = $input.first().json || {};
const buildNode = $item(0).$node["Build 1‑manifest.json"]?.json || {};
const manifest = input.manifest || buildNode.manifest;
const manifestKey = input.r2Key || input.manifestKey || input.orderUpsert?.one_manifest_url || buildNode.r2Key || buildNode.manifestKey || buildNode.orderUpsert?.one_manifest_url || manifest?.artifacts?.manifestKey || null;

if (!manifestKey) {
  throw new Error('Missing manifest key for W0 fallback path');
}

return [{
  json: {
    r2Key: manifestKey,
    manifestKey,
    orderId: input.orderId || input.orderUpsert?.orderId || input.orderUpsert?.order_id || buildNode.orderId || buildNode.orderUpsert?.orderId || buildNode.orderUpsert?.order_id || null,
    manifest,
    orderUpsert: input.orderUpsert || buildNode.orderUpsert || null,
    _config: input._config || $item(0).$node["Normalize Payload"]?.json?._config || {},
  },
}];

// Extract & sanitize dedication from normalized shape
const norm = $input.first().json || {};

function fromItem(it){
  const fields = it.customizations || it.customizationFields || it.options || [];
  for (const f of (fields||[])){
    const name = (f.name||f.label||f.type||'').toLowerCase();
    if (name.includes('dedication') || name.includes('message') || name.includes('note')){
      const v = (f.value||f.text||f.stringValue||'')+'';
      if (v.trim()) return v;
    }
  }
  return null;
}

// Check multiple possible locations for dedication
let found = '';
const rawBody = norm._raw?.body || {};

// 1. Check top-level in normalized object
if (!found && norm.dedication) found = String(norm.dedication);

// 2. Check _raw.body.dedication (direct field)
if (!found && rawBody.dedication) found = String(rawBody.dedication);
if (!found && rawBody.Dedication) found = String(rawBody.Dedication);

// 3. Check characterSpecs variations in _raw.body
if (!found && rawBody.characterSpecs?.dedication) found = String(rawBody.characterSpecs.dedication);
if (!found && rawBody.character_specs?.dedication) found = String(rawBody.character_specs.dedication);
if (!found && rawBody.CharacterSpecs?.dedication) found = String(rawBody.CharacterSpecs.dedication);

// 4. Check normalized characterSpecs (if it exists after normalization)
if (!found && norm.characterSpecs?.dedication) found = String(norm.characterSpecs.dedication);

// 5. Check items array for customizations
if (!found && Array.isArray(norm.items)) {
  for (const li of norm.items){
    const maybe = fromItem(li);
    if (maybe){ found = maybe; break; }
  }
}

// 6. Fallback: check _raw.dedication (old location)
if (!found && norm._raw?.dedication) found = String(norm._raw.dedication);

// sanitize
const MAX_CHARS = 500, MAX_LINES = 6;
let t = (found || '')
  .replace(/[\u0000-\u0008\u000B-\u001F\u007F]/g,'')
  .replace(/\r\n?/g,'\n').replace(/[ \t]{2,}/g,' ');
t = t.split('\n').map(l => l.trimEnd()).join('\n').trim();
if (t.length > MAX_CHARS) t = t.slice(0, MAX_CHARS).trim();
t = t.split('\n').slice(0, MAX_LINES).join('\n');
const esc = s => s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

return [{
  json: {
    ...norm,
    dedication: { raw: found || '', text: t, htmlSafe: esc(t) }
  }
}];

// Accepts many shapes (Amazon Custom / backend forwarder / mock)
// Normalize core fields and optional specs. Dedication is handled in the next node.
// Gets CONFIG from earlier node execution (CONFIG runs before Mock Order)
const raw = $input.first().json || {};
const config = $item(0).$node["CONFIG (PRODUCTION)"]?.json || {};

function safe(o){ return (o && typeof o === 'object') ? o : {}; }
function coerceStr(v){ return (v==null) ? undefined : String(v); }
function num(v){ const n = Number(v); return Number.isFinite(n) ? n : undefined; }
function extractItems(r){ return Array.isArray(r.items) ? r.items : (Array.isArray(r.lineItems) ? r.lineItems : []); }
// orderId (per-book synthetic ID) MUST take precedence over amazonOrderId (group root).
// If amazonOrderId comes first, a sibling payload with both fields set would derive
// orderId = root group ID, making isSiblingOrder = false and bypassing all sibling logic.
function extractOrderId(r){ return r.orderId || r.id || r.amazonOrderId || 'UNKNOWN-ORDER'; }
// Sibling orders have synthetic ID: <rootOrderId>-item-<itemId>. Derive root for group queries.
function deriveRootOrderId(oid){
  const m = String(oid || '').match(/^(.+)-item-[^-]+$/);
  return m ? m[1] : oid;
}

// Map pronouns/gender to clothing style
function mapClothingStyle(pronouns, explicitClothing) {
  // If clothing style is explicitly provided, use it
  if (explicitClothing && String(explicitClothing).trim()) {
    return String(explicitClothing).trim();
  }

  // Map from pronouns if no explicit clothing
  if (!pronouns) return 'tee-shorts'; // default

  const p = String(pronouns).toLowerCase().trim();

  // girl or she/her → dress
  if (p.includes('girl') || p.includes('she')) {
    return 'dress';
  }

  // boy, he/him, they/them → tee-shorts
  if (p.includes('boy') || p.includes('he') || p.includes('they')) {
    return 'tee-shorts';
  }

  // default
  return 'tee-shorts';
}

const orderId = extractOrderId(raw);
const rootOrderId = deriveRootOrderId(orderId);
const isSiblingOrder = rootOrderId !== orderId;
const items = extractItems(raw);

// Optional specs
const cs = safe(raw.characterSpecs);
const bs = safe(raw.bookSpecs);
const od = safe(raw.orderDetails);
const shipping = safe(od.shippingAddress);

const characterSpecs = {
  childName: coerceStr(cs.childName),
  skinTone: coerceStr(cs.skinTone),
  hairColor: coerceStr(cs.hairColor),
  hairStyle: coerceStr(cs.hairStyle),
  age: num(cs.age),
  pronouns: coerceStr(cs.pronouns),
  favoriteColor: coerceStr(cs.favoriteColor),
  animalGuide: coerceStr(cs.animalGuide),
  clothingStyle: mapClothingStyle(cs.pronouns, cs.clothingStyle), // Map from pronouns if not provided
  hometown: coerceStr(cs.hometown || cs.homeTown || cs.home_town),
};

const bookSpecs = {
  title: coerceStr(bs.title),
  totalPages: num(bs.totalPages),
  format: coerceStr(bs.format),
  bookType: coerceStr(bs.bookType),
};

// D2C/checkout uses address_line1, postal_code; Amazon uses address, zip. Resolve both.
const addr = coerceStr(shipping.address || shipping.address_line1 || shipping.address_line_1 || shipping.addressLine1);
const zipVal = coerceStr(shipping.zip || shipping.postal_code || shipping.postalCode);
const orderDetails = {
  quantity: num(od.quantity) || 1,
  shippingAddress: {
    name: coerceStr(shipping.name),
    address: addr,
    address_line_1: addr,
    city: coerceStr(shipping.city),
    state: coerceStr(shipping.state),
    state_code: coerceStr(shipping.state_code || shipping.state),
    zip: zipVal,
    postal_code: zipVal,
    phone: coerceStr(shipping.phone || shipping.phoneNumber || shipping.phone_number),
    phone_number: coerceStr(shipping.phone_number || shipping.phone || shipping.phoneNumber),
    country: coerceStr(shipping.country) || 'US',
  }
};

return [{
  json: {
    _raw: raw,
    _config: config, // Merge config into flow for downstream nodes
    orderId,
    amazonOrderId: raw.amazonOrderId || null,
    marketplaceId: raw.marketplaceId || null,
    rootOrderId,
    isSiblingOrder,
    // legacy fields for compatibility
    buyer: raw.buyer || {},
    purchaseDate: raw.purchaseDate || raw.createdAt || null,
    // normalized fields
    status: coerceStr(raw.status) || 'queued_for_processing',
    orderDate: coerceStr(raw.orderDate) || new Date().toISOString(),
    customerEmail: coerceStr(raw.customerEmail),
    items,
    characterSpecs,
    bookSpecs,
    orderDetails
  }
}];

// Central config (fill tokens/keys after import)
// n8n webhook wraps POST data in .body — extract it so order fields are at top level
